 *   - something thrown          -> "primary=" + that exception's message,
 *                                  then " | suppressed=" + the message of each
 *                                  exception in getSuppressed(), in order.
 *
 * A try-with-resources closes its resources in REVERSE order after the body,
 * and if the body already failed, an exception from close() is attached to the
 * body's exception as a SUPPRESSED exception rather than replacing it.
 *
 * Example: first fails on write and second fails on close ->
 *   "primary=write failed in A | suppressed=close failed in B"
 */
class AuditSink implements AutoCloseable {
    /* Provided -- do not edit. */
    private final String name;
    private final boolean failOnWrite;
    private final boolean failOnClose;

    AuditSink(String name, boolean failOnWrite, boolean failOnClose) {
        this.name = name;
        this.failOnWrite = failOnWrite;
        this.failOnClose = failOnClose;
    }

    void write(String line) {
        if (failOnWrite) {
            throw new IllegalStateException("write failed in " + name);
        }
    }

    @Override
    public void close() {
        if (failOnClose) {
            throw new IllegalStateException("close failed in " + name);
        }
    }
}

