public class SuppressedCollectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static AuditSink sink(String name, boolean failOnWrite, boolean failOnClose) {
        return new AuditSink(name, failOnWrite, failOnClose);
    }

    static Object report(AuditSink first, AuditSink second) {
        try {
            return SuppressedCollector.report(first, second);
        } catch (Throwable crash) {
            return "report threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("both sinks behave", "ok",
                report(sink("A", false, false), sink("B", false, false)));
        check("the first write fails", "primary=write failed in A",
                report(sink("A", true, false), sink("B", false, false)));
        check("the second write fails", "primary=write failed in B",
                report(sink("A", false, false), sink("B", true, false)));
        check("only a close fails", "primary=close failed in B",
                report(sink("A", false, false), sink("B", false, true)));
        check("write failure keeps a close failure as suppressed",
                "primary=write failed in A | suppressed=close failed in B",
                report(sink("A", true, false), sink("B", false, true)));
        check("two close failures: the second sink closes first",
                "primary=close failed in B | suppressed=close failed in A",
                report(sink("A", false, true), sink("B", false, true)));
        check("a body failure suppresses both close failures",
                "primary=write failed in A | suppressed=close failed in B | suppressed=close failed in A",
                report(sink("A", true, true), sink("B", false, true)));
        check("the second write fails while the first sink cannot close",
                "primary=write failed in B | suppressed=close failed in A",
                report(sink("A", false, true), sink("B", true, false)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

