public class SuppressedCollector {

    public static String report(AuditSink first, AuditSink second) {
        try (AuditSink a = first; AuditSink b = second) {
            a.write("entry");
            b.write("entry");
        } catch (Throwable primary) {
            StringBuilder report = new StringBuilder("primary=").append(primary.getMessage());
            for (Throwable extra : primary.getSuppressed()) {
                report.append(" | suppressed=").append(extra.getMessage());
            }
            return report.toString();
        }
        return "ok";
    }
}
